    31	        // Resolve path relative to baseDir
    32	        if (!str_starts_with($path, '/')) {
    33	            $path = $this->baseDir . '/' . $path;
    34	        }
    35	
    36	        $path = rtrim($path, '/');
    37	
    38	        if (!is_dir($path)) {
    39	            return "Error: '{$path}' is not a directory";
    40	        }
    41	
    42	        $entries = @scandir($path);
    43	        if ($entries === false) {
    44	            return "Error: Cannot read directory '{$path}'";
    45	        }
    46	
    47	        // Filter out . and ..
    48	        $entries = array_filter($entries, fn($e) => $e !== '.' && $e !== '..');
    49	        $entries = array_values($entries);
    50	
    51	        if ($entries === []) {
    52	            return "Directory '{$path}' is empty";
    53	        }
    54	
    55	        // Sort: directories first, then files
    56	        usort($entries, function($a, $b) use ($path) {
    57	            $aIsDir = is_dir($path . '/' . $a);
    58	            $bIsDir = is_dir($path . '/' . $b);
    59	            if ($aIsDir && !$bIsDir) return -1;
    60	            if (!$aIsDir && $bIsDir) return 1;
    61	            return strcasecmp($a, $b);
    62	        });
    63	
    64	        // Limit entries
    65	        $total = count($entries);
    66	        $entries = array_slice($entries, 0, $this->maxEntries);
    67	
    68	        // Format output
    69	        $lines = [];
    70	        foreach ($entries as $entry) {
    71	            $fullPath = $path . '/' . $entry;
    72	            $type = is_dir($fullPath) ? '[dir]' : '[file]';
    73	            $lines[] = "{$type} {$entry}";
    74	        }
    75	
    76	        $output = implode("\n", $lines);
    77	
    78	        if ($total > $this->maxEntries) {
    79	            $output .= "\n... and " . ($total - $this->maxEntries) . " more entries";
    80	        }
    81	
    82	        return $output;
